import{_ as n,a0 as r,w as i,s as u,I as t,x as s,a1 as p,A as l,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"你需要知道的 DevSecOps 流程及工具 | LCTT x X-CMD","titleTemplate":false,"description":"你需要知道的 DevSecOps 流程及工具 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"你需要知道的 DevSecOps 流程及工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"你需要知道的 DevSecOps 流程及工具 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191010 DevSecOps pipelines and tools- What you need to know","title":"你需要知道的 DevSecOps 流程及工具","tag":"201910","desc":""},"relativePath":"201910/20191010 DevSecOps pipelines and tools- What you need to know.md","filePath":"[post].md"}'),a={name:"201910/20191010 DevSecOps pipelines and tools- What you need to know.md"};function v(D,e,S,f,O,m){const o=r("Link");return i(),u("div",null,[e[25]||(e[25]=t("h1",{id:"你需要知道的-devsecops-流程及工具",tabindex:"-1"},[s("你需要知道的 DevSecOps 流程及工具 "),t("a",{class:"header-anchor",href:"#你需要知道的-devsecops-流程及工具","aria-label":"Permalink to “你需要知道的 DevSecOps 流程及工具”"},"​")],-1)),e[26]||(e[26]=t("blockquote",null,[t("p",null,"DevSecOps 对 DevOps 进行了改进，以确保安全性仍然是该过程的一个重要部分。")],-1)),e[27]||(e[27]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/201910/23/002010fvzh282e8ghhdzpk.jpg",alt:""})],-1)),e[28]||(e[28]=t("p",null,"到目前为止，DevOps 在 IT 世界中已广为人知，但其并非完美无缺。试想一下，你在一个项目的现代应用程序交付中实施了所有 DevOps 工程实践。你已经到达开发流程的末尾，但是渗透测试团队（内部或外部）检测到安全漏洞并提出了报告。现在，你必须重新启动所有流程，并要求开发人员修复该漏洞。",-1)),e[29]||(e[29]=t("p",null,"在基于 DevOps 的软件开发生命周期（SDLC）系统中，这并不繁琐，但它确实会浪费时间并影响交付进度。如果从 SDLC 初期就已经集成了安全性，那么你可能已经跟踪到了该故障，并在开发流程中就消除了它。但是，如上述情形那样，将安全性推到开发流程的最后将导致更长的开发生命周期。",-1)),e[30]||(e[30]=t("p",null,"这就是引入 DevSecOps 的原因，它以自动化的方式巩固了整个软件交付周期。",-1)),t("p",null,[e[3]||(e[3]=s("在现代 DevOps 方法中，组织广泛使用容器托管应用程序，我们看到 ",-1)),p(o,{href:"https://opensource.com/resources/what-is-kubernetes"},{default:l(()=>[...e[0]||(e[0]=[s("Kubernetes",-1)])]),_:1}),e[4]||(e[4]=s(" 和 ",-1)),p(o,{href:"https://opensource.com/article/18/9/what-istio"},{default:l(()=>[...e[1]||(e[1]=[s("Istio",-1)])]),_:1}),e[5]||(e[5]=s(" 使用的较多。但是，这些工具都有其自身的漏洞。例如，云原生计算基金会（CNCF）最近完成了一项 ",-1)),p(o,{href:"https://www.cncf.io/blog/2019/08/06/open-sourcing-the-kubernetes-security-audit/"},{default:l(()=>[...e[2]||(e[2]=[s("kubernetes 安全审计",-1)])]),_:1}),e[6]||(e[6]=s("，发现了几个问题。DevOps 开发流程中使用的所有工具在流程运行时都需要进行安全检查，DevSecOps 会推动管理员去监视工具的存储库以获取升级和补丁。",-1))]),e[31]||(e[31]=t("h3",{id:"什么是-devsecops",tabindex:"-1"},[s("什么是 DevSecOps? "),t("a",{class:"header-anchor",href:"#什么是-devsecops","aria-label":"Permalink to “什么是 DevSecOps?”"},"​")],-1)),e[32]||(e[32]=t("p",null,"与 DevOps 一样，DevSecOps 是开发人员和 IT 运营团队在开发和部署软件应用程序时所遵循的一种思维方式或文化。它将主动和自动化的安全审计以及渗透测试集成到敏捷应用程序开发中。",-1)),t("p",null,[e[8]||(e[8]=s("要使用 ",-1)),p(o,{href:"https://resources.whitesourcesoftware.com/blog-whitesource/devsecops"},{default:l(()=>[...e[7]||(e[7]=[s("DevSecOps",-1)])]),_:1}),e[9]||(e[9]=s("，你需要：",-1))]),e[33]||(e[33]=d('<ul><li>从 SDLC 开始就引入安全性概念，以最大程度地减少软件代码中的漏洞。</li><li>确保每个人（包括开发人员和 IT 运营团队）共同承担在其任务中遵循安全实践的责任。</li><li>在 DevOps 工作流程开始时集成安全控件、工具和流程。这些将在软件交付的每个阶段启用自动安全检查。</li></ul><p>DevOps 一直致力于在开发和发布过程中包括安全性以及质量保证（QA）、数据库管理和其他所有方面。然而，DevSecOps 是该过程的一个演进，以确保安全永远不会被遗忘，成为该过程的一个重要部分。</p><h3 id="了解-devsecops-流程" tabindex="-1">了解 DevSecOps 流程 <a class="header-anchor" href="#了解-devsecops-流程" aria-label="Permalink to “了解 DevSecOps 流程”">​</a></h3><p>典型的 DevOps 流程有不同的阶段；典型的 SDLC 流程包括计划、编码、构建、测试、发布和部署等阶段。在 DevSecOps 中，每个阶段都会应用特定的安全检查。</p><ul><li><strong>计划</strong>：执行安全性分析并创建测试计划，以确定在何处、如何以及何时进行测试的方案。</li><li><strong>编码</strong>：部署整理工具和 Git 控件以保护密码和 API 密钥。</li><li><strong>构建</strong>：在构建执行代码时，请结合使用静态应用程序安全测试（SAST）工具来跟踪代码中的缺陷，然后再部署到生产环境中。这些工具针对特定的编程语言。</li><li><strong>测试</strong>：在运行时使用动态应用程序安全测试（DAST）工具来测试您的应用程序。 这些工具可以检测与用户身份验证，授权，SQL 注入以及与 API 相关的端点相关的错误。</li><li><strong>发布</strong>：在发布应用程序之前，请使用安全分析工具来进行全面的渗透测试和漏洞扫描。</li><li><strong>部署</strong>：在运行时完成上述测试后，将安全的版本发送到生产中以进行最终部署。</li></ul><h3 id="devsecops-工具" tabindex="-1">DevSecOps 工具 <a class="header-anchor" href="#devsecops-工具" aria-label="Permalink to “DevSecOps 工具”">​</a></h3><p>SDLC 的每个阶段都有可用的工具。有些是商业产品，但大多数是开源的。在我的下一篇文章中，我将更多地讨论在流程的不同阶段使用的工具。</p><p>随着基于现代 IT 基础设施的企业安全威胁的复杂性增加，DevSecOps 将发挥更加关键的作用。然而，DevSecOps 流程将需要随着时间的推移而改进，而不是仅仅依靠同时实施所有安全更改即可。这将消除回溯或应用交付失败的可能性。</p><hr>',9)),t("p",null,[e[11]||(e[11]=s("via: ",-1)),p(o,{href:"https://opensource.com/article/19/10/devsecops-pipeline-and-tools"},{default:l(()=>[...e[10]||(e[10]=[s("https://opensource.com/article/19/10/devsecops-pipeline-and-tools",-1)])]),_:1})]),t("p",null,[e[16]||(e[16]=s("作者：",-1)),p(o,{href:"https://opensource.com/users/sagarnangare"},{default:l(()=>[...e[12]||(e[12]=[s("Sagar Nangare",-1)])]),_:1}),e[17]||(e[17]=s(" 选题：",-1)),p(o,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[13]||(e[13]=[s("lujun9972",-1)])]),_:1}),e[18]||(e[18]=s(" 译者：",-1)),p(o,{href:"https://github.com/lnrCoder"},{default:l(()=>[...e[14]||(e[14]=[s("lnrCoder",-1)])]),_:1}),e[19]||(e[19]=s(" 校对：",-1)),p(o,{href:"https://github.com/wxy"},{default:l(()=>[...e[15]||(e[15]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[22]||(e[22]=s("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[20]||(e[20]=[s("LCTT",-1)])]),_:1}),e[23]||(e[23]=s(" 原创编译，",-1)),p(o,{href:"https://linux.cn/"},{default:l(()=>[...e[21]||(e[21]=[s("Linux中国",-1)])]),_:1}),e[24]||(e[24]=s(" 荣誉推出",-1))])])}const b=n(a,[["render",v]]);export{C as __pageData,b as default};
